#include <Arduino.h>

// ESP32-C3 SuperMini
// Puente transparente USB <-> UART RN2903
// UART: 57600 baudios, 8N1
// RX = GPIO4
// TX = GPIO5

HardwareSerial LoRa(1);

void setup() {
  Serial.begin(115200);

  // Inicializar UART hacia el RN2903
  LoRa.begin(57600, SERIAL_8N1, 4, 5);

  delay(500);
  Serial.println("Aqui estoy - Puente USB/UART activo");
}

void loop() {
  // USB -> RN2903
  while (Serial.available() > 0) {
    LoRa.write(Serial.read());
  }

  // RN2903 -> USB
  while (LoRa.available() > 0) {
    Serial.write(LoRa.read());
  }
}
